  'royal-fruits', 'royal-dice', 'royal-limbo', 'royal-mines', 'royal-plinko',
  'royal-keno', 'github-craps', 'github-diamonds', 'github-crash', 'github-sic-bo', PENALTY_GAME,
] as const;
